    function __ESBMC_assume(bool) internal pure {}

    function run(bool doDeposit, uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= depositAmount);
        require(true);

        address ownerBefore = c.Owner(); if (__ESBMC_reverted()) return;

        c.withdraw(); if (__ESBMC_reverted()) return;

        uint cBalAfter = address(c).balance;
        uint testBalAfter = address(this).balance;

        assert(address(this) == ownerBefore && cBalAfter == 0);
    }

    receive() external payable {}
}

