// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX4 c;

    function setUp() public {
        c = new MultiplicatorX4();
    }

    function _run(bool doDeposit, uint256 depositAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        vm.assume(true);
        address ownerBefore;
        try c.Owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        try c.withdraw() {} catch { return; }
        uint cBalAfter = address(c).balance;
        uint testBalAfter = address(this).balance;
        assertTrue(address(this) == ownerBefore && cBalAfter == 0);
    }

    function testFuzz_run(bool doDeposit, uint256 depositAmount) public {
        _run(doDeposit, depositAmount);
    }

    receive() external payable {}
}
